// n8n Code node "Set window". Input: the newest-record query. Output: one item with the 9-week window.
const newest = $input.first().json.results?.[0]?.newest;
if (!newest) return [{ json: { ok: false, reason: "The city API returned no newest record." } }];
const vanDate = (d) => new Date(d).toLocaleDateString("en-CA", { timeZone: "America/Vancouver" });
const addDays = (iso, n) => { const d = new Date(iso + "T12:00:00Z"); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };
const week_ending = vanDate(newest);
const ageHours = (Date.now() - new Date(newest).getTime()) / 36e5;
if (ageHours > 48) return [{ json: { ok: false, reason: `The newest 3-1-1 record is ${Math.round(ageHours)} hours old.` } }];
return [{ json: {
  ok: true,
  newest_record: newest,
  week_ending,
  window_start: addDays(week_ending, -62),   // 9 weeks of 7 days, inclusive
  window_end_exclusive: addDays(week_ending, 1),
  this_week_start: addDays(week_ending, -6),
} }];

// n8n Code node "Build collected". Reads the window and both queries by node name.
const w = $("Set window").first().json;
const daily = $("Daily counts by type").all().map((i) => i.json);
const areas = $("This week by area").all().map((i) => i.json);
const addDays = (iso, n) => { const d = new Date(iso + "T12:00:00Z"); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };
const daysBetween = (a, b) => Math.round((new Date(b + "T12:00:00Z") - new Date(a + "T12:00:00Z")) / 864e5);
const weeks = Array.from({ length: 9 }, (_, k) => addDays(w.week_ending, -7 * (8 - k)));

const types = new Map();
const entry = (t) => {
  if (!types.has(t)) types.set(t, { type: t, weekly: weeks.map((we) => ({ week_ending: we, count: 0 })), by_area: [], unknown_area: 0 });
  return types.get(t);
};
for (const r of daily) {
  if (!r.service_request_type || !r.day) continue;
  const k = 8 - Math.floor(daysBetween(r.day, w.week_ending) / 7);
  if (k < 0 || k > 8) continue;
  entry(r.service_request_type).weekly[k].count += r.n;
}
for (const r of areas) {
  if (!r.service_request_type) continue;
  const e = entry(r.service_request_type);
  if (r.local_area) e.by_area.push({ area: r.local_area, count: r.n });
  else e.unknown_area += r.n;
}
for (const e of types.values()) e.by_area.sort((a, b) => b.count - a.count);
if (!types.size) return [{ json: { ok: false, reason: "The city API returned no 3-1-1 rows for the window." } }];

return [{ json: {
  ok: true,
  dataset: "3-1-1 service requests",
  source: "City of Vancouver open data, 3-1-1 service requests",
  source_url: "https://opendata.vancouver.ca/explore/dataset/3-1-1-service-requests/",
  newest_record: w.newest_record,
  week_ending: w.week_ending,
  weeks,
  types: [...types.values()],
} }];

// n8n Code node "No data today". Reached when the city API fails or the window check says no.
const j = $input.first().json;
const reason = j.reason || `The City of Vancouver API did not answer: ${j.error?.message || j.message || "unknown error"}`;
return [{ json: { ok: false, dataset: "3-1-1 service requests", reason } }];
